const RIG=DATA.rig;let resolution=48,view='armor',gold='normal',ready=false;
const images={armor:{},frame:{},variants:{},goldMask:{},gold:{},goldVariants:{},off:{},debug:{}};
const T=(x,y)=>[1,0,0,1,x,y],mul=(a,b)=>[a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]],point=(m,p)=>[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]];const rot=d=>{let a=d*Math.PI/180;return [Math.cos(a),Math.sin(a),-Math.sin(a),Math.cos(a),0,0]},pivot=(p,d)=>mul(T(...p),mul(rot(d),T(-p[0],-p[1])));
function poseAt(m,t){const k=motions[m].keys;let i=0;while(i<k.length-2&&t>k[i+1].t)i++;let a=k[i],b=k[i+1],u=Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t)));u=u*u*(3-2*u);let keys=new Set([...Object.keys(a.pose),...Object.keys(b.pose)]);return Object.fromEntries([...keys].map(n=>[n,(a.pose[n]||0)*(1-u)+(b.pose[n]||0)*u]))}
const S=RIG.scale,base=[S,0,0,S,24-64*S,44-112*S];
function rawTransforms(p){const out={};function resolve(n){if(out[n])return out[n];const parent=RIG.parents[n];return out[n]=mul(parent?resolve(parent):mul(T(p.x||0,0),pivot(RIG.joints.pelvis,p.root||0)),pivot(RIG.joints[n],p[n]||0))}Object.keys(RIG.joints).forEach(resolve);return out}
const outlines={};
function choose(n,p){return n.startsWith('hand_')&&(p['open_'+n.slice(5)]||0)>.49?n+'_open':n}
function transforms(m,t){const p=poseAt(m,t),raw=rawTransforms(p),mats={};let lo=Infinity,hi=-Infinity,top=Infinity,bottom=-Infinity;for(const n of RIG.drawOrder){let mat=mul(base,raw[n]);mats[n]=mat;for(const xy of outlines[choose(n,p)]||outlines[n]||[]){let [x,y]=point(mat,xy);lo=Math.min(lo,x);hi=Math.max(hi,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}}
// Ground is the lowest visible point. During collapse this is body/hand rather than heels.
// Do not scale individual poses. Shift within the 48px field, and flag oversize.
let dx=lo<1?1-lo:hi>47?47-hi:0,dy=44-bottom;
if(m==='win'){let jump=0;for(const [start,end,height] of [[.09,.31,5.5],[.37,.61,6.0]]){if(t>start&&t<end){const u=(t-start)/(end-start);jump=4*height*u*(1-u)}}dy-=Math.min(jump,Math.max(0,top+dy-1));}for(const n of RIG.drawOrder)mats[n]=mul(T(dx,dy),mats[n]);return {mats,p,bounds:[lo+dx,top+dy,hi+dx,bottom+dy]}}
const scratch=document.createElement('canvas');
function renderUnit(canvas,m,t,side){const n=resolution,s=n/48;if(scratch.width!==n||scratch.height!==n){scratch.width=n;scratch.height=n}if(canvas.width!==n||canvas.height!==n){canvas.width=n;canvas.height=n}const ctx=scratch.getContext('2d',{willReadFrequently:true});ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,n,n);ctx.imageSmoothingEnabled=false;const {mats,p,bounds}=transforms(m,t);function draw(name,img){let mat=mats[name];ctx.setTransform(...mat.map(v=>v*s));ctx.drawImage(img,0,0)}for(const name of RIG.drawOrder)draw(name,images.frame[name]);if(view!=='frame')for(const name of RIG.drawOrder){let k=choose(name,p);let img=k!==name?(gold==='gold'?images.goldVariants[k]:images.variants[k]):view==='parts'?images.debug[name]:gold==='gold'?images.gold[name]:(p.off||0)>.55?images.off[name]:images.armor[name];draw(name,img)}if(view==='joints'){ctx.setTransform(s,0,0,s,0,0);ctx.fillStyle='#ffe367';for(const [name,j] of Object.entries(RIG.joints)){const q=point(mats[name],j);ctx.fillRect(Math.floor(q[0]),Math.floor(q[1]),1,1)}ctx.fillStyle='#00efff';for(const {part,point:q} of Object.values(RIG.mounts)){const r=point(mats[part],q);ctx.fillRect(Math.floor(r[0]),Math.floor(r[1]),1,1)}}const dest=canvas.getContext('2d');dest.setTransform(1,0,0,1,0,0);dest.clearRect(0,0,n,n);dest.imageSmoothingEnabled=false;if(side)dest.setTransform(-1,0,0,1,n,0);dest.drawImage(scratch,0,0);dest.setTransform(1,0,0,1,0,0);return {mats,bounds}}

function canvasOf(img){let cv=document.createElement('canvas');cv.width=cv.height=128;let cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0);return [cv,cx]}
const purples=RIG.palette,golds=[[42,39,45],[100,70,35],[142,98,40],[184,133,51],[221,169,66],[249,205,105],[255,230,159],[245,242,235],[250,248,244],[214,214,217],[164,164,171],[111,111,121],[239,181,75],[255,228,144],[164,116,91],[225,176,117],[252,219,162],[133,107,60],[231,195,112],[255,249,218]];
function recolor(img,kind,index){let [cv,cx]=canvasOf(img),im=cx.getImageData(0,0,128,128);for(let i=0;i<im.data.length;i+=4){let d=im.data;if(!d[i+3])continue;if(kind==='gold'){let k=purples.findIndex(p=>p.every((v,j)=>v===d[i+j]));if(k>=0)d.set(golds[k],i)}else if(kind==='off'){if((d[i+2]>d[i]+40&&d[i+1]>d[i]+20)||(d[i]>200&&d[i+2]>170&&d[i+1]<190))d.set([77,63,92],i)}else if(kind==='debug'){d.set([60+(index*71)%195,60+(index*43)%195,60+(index*101)%195],i)}}cx.putImageData(im,0,0);return cv}
async function start(){for(const k of ['armor','frame','variants','goldMask'])for(const [n,url] of Object.entries(DATA[k])){let img=new Image();img.src=url;images[k][n]=img}await Promise.all(Object.values(images).flatMap(p=>Object.values(p).map(i=>i.decode())));for(const [n,img] of Object.entries({...images.armor,...images.variants})){const [cv,cx]=canvasOf(img),d=cx.getImageData(0,0,128,128).data,pts=[];for(let y=0;y<128;y++)for(let x=0;x<128;x++)if(d[(y*128+x)*4+3]){if(x===0||y===0||x===127||y===127||!d[(y*128+x-1)*4+3]||!d[(y*128+x+1)*4+3]||!d[((y-1)*128+x)*4+3]||!d[((y+1)*128+x)*4+3])pts.push([x,y],[x+1,y+1],[x+1,y],[x,y+1])}outlines[n]=pts}for(const [i,n] of RIG.drawOrder.entries()){images.gold[n]=recolor(images.armor[n],'gold',i);images.off[n]=recolor(images.armor[n],'off',i);images.debug[n]=recolor(images.armor[n],'debug',i)}for(const [n,img] of Object.entries(images.variants))images.goldVariants[n]=recolor(img,'gold',0);ready=true;}

