  if(!s||s.mode!==mode||s.gold!==form||s.flash!==flash){s={start:now,mode,gold:form,flash,t:0,delay:!reduced&&mode==='hit'?Number(cv.closest?.('.pilot')?.dataset.hitDelay||0):0};states.set(cv,s)}
